import{_ as d,o as a,c as r,a3 as p}from"./chunks/framework.bvEHUNtb.js";const c=JSON.parse('{"title":"体用生克篇之三：三要灵应篇","description":"从耳闻、目见与当下情境，理解感象与克应的关系。","frontmatter":{"title":"体用生克篇之三：三要灵应篇","description":"从耳闻、目见与当下情境，理解感象与克应的关系。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/three-essential-responses.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/three-essential-responses.md","lastUpdated":1786982540000}'),n={name:"yijing/meihua-yishu/ti-yong-sheng-ke/three-essential-responses.md"};function e(s,t,o,i,l,h){return a(),r("div",null,[...t[0]||(t[0]=[p(`<h1 id="【体用生克篇之三】三要灵应篇" tabindex="-1">【体用生克篇之三】三要灵应篇 <a class="header-anchor" href="#【体用生克篇之三】三要灵应篇" aria-label="Permalink to &quot;【体用生克篇之三】三要灵应篇&quot;">​</a></h1><blockquote><p>本篇是梅花易数「感象」功夫的集大成。前几篇讲规则，这篇讲的是规则背后的感知状态。</p></blockquote><hr><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="三要灵应篇序" tabindex="-1">三要灵应篇序 <a class="header-anchor" href="#三要灵应篇序" aria-label="Permalink to &quot;三要灵应篇序&quot;">​</a></h3><p>夫《易》者，性理之学也。性理，具于人心者也。当其方寸湛然，灵台皎洁，无一毫之干，无一尘之累，斯时也，性理具在而《易》存吾心，浑然是《易》也，其先天之《易》也。乃夫虑端一起，事根忽萌，物之着心，如云之蔽室，如尘之蒙镜，斯时也，汩没茫昧，而向之《易》存吾心者，泯焉尔。故三要之妙，在于运耳、目、心三者之虚灵，俾应于事物也，耳之聪，目之明，吾心实总乎聪明。盖事根于心，心该乎事，然事之未萌也，虽鬼神莫测其端，而吉凶祸福，无门可入。故先师曰：「思虑未动，鬼神不知；不由乎我，更由乎谁？」故事萌于心，鬼神知之矣。吉凶悔吝有其数，然吾预知之，何道欤？必曰：「求诸吾心易之妙而已矣。」于是寂然不动，静虑诚存，观变玩占，运乎三要，必使视之不见，吾见之；听之不闻者，吾闻之；如形之见视，如音之见告，吾之了然鉴之。则《易》之为卜筮之道，而《易》在吾心矣。三要不虚，而灵应之妙斯得也。是道也，寓至精至神之理，百姓日用而不知，安得圆通三昧者，与之论欤！此先师刘先生（江夏人，号湛然子）得之王屋山人高处士云岩。</p><p>宝庆四年，仲夏既望，清灵子朱虚拜首序</p><h3 id="三要灵应篇" tabindex="-1">三要灵应篇 <a class="header-anchor" href="#三要灵应篇" aria-label="Permalink to &quot;三要灵应篇&quot;">​</a></h3><p>三要者，运耳、目、心三者之要也。灵应者，灵妙而应验也。夫耳之于听，目之于视，心之于思，三者为人一身之要，而万物之理不出于视听之外。占决之际，寂闻澄虑，静观万物，而听其音，知吉凶，见其形，知善恶，察其理，知祸福，皆可为占卜之验。如谷之应声，如影之随形，灼然可见也。其理出于《周易》「远取诸物，近取诸身」之法。是编则出于先贤先师，采世俗之语为例用之者：鬼谷子、严君平、东方朔、诸葛孔明；继而得者：邵康节、邵伯温、刘伯温、牛思晦、牛思继、高处士、刘湛然、富寿子、泰然子、朱清灵子。其年代相传不一，而不知其姓名者不与焉。</p><p>原夫天高地厚，万物散殊，阴浊阴清，五气顺布，祸福莫逃乎数，吉凶皆有其机。人为万物之灵，心乃一身之主，目寓而为形于色，耳得而为音于声，三要总之，万物备矣。</p><p>此乃天地万物之灵，而耳、目、心三者之要，故曰三要也。</p><p>是以遇吉兆而有吉，见凶识而不免乎凶。物之圆者事成，缺事败。此理断然，夫复何疑？</p><p>此乃占物克应，见吉则吉，遇凶则凶。</p><p>是以云开见日，事必增辉；烟雾障空，物当失色。忽颠风而飘荡，遇震雷以虚惊。月忽当面，宜近清光。雨可沾衣，可蒙恩泽。</p><p>此乃仰观天文，以验人事。</p><p>重山为阻隔之际，重泽为浸润之深。水流而事通，土积而事滞。石乃坚心始得，沙乃放手即开。浪激主波涛之惊，坡崩主田土之失。旱沼之旁，心力俱竭，枯林之下，相貌皆衰。</p><p>此来俯察地理，以验人事。</p><p>适逢人品之来，实为事体之应。故荣宦显官，宜见其贵；富商匠贾，可问乎财。儿童哭泣忧子孙，吏卒叫嚣忌官讼。二男二女，重婚之义；一僧一道，独处之端。妇人笑语，则阴喜相逢；女子牵连，则阴私见累。匠氏，主门庭改换；宰夫，则骨肉分离。逢猎者，得野外之财；见渔者，有水边之利。见妊妇，则事荫于内；遇瞽者，则虑根于心。</p><p>此乃人品之应，以验人事。</p><p>至于摇手而莫为，或掉头而不肯，拭目而喷嚏者方泣；搔首而弹垢者有忧。足动者有行，交臂者有失。屈指者多阻节，嘘气者主悲忧。舌出掉者有是非，背相向者防闪失。偶攘臂者，争夺乃得；偶下膝者，屈抑而求。</p><p>此乃「近取诸身」之应。</p><p>若逢童子授书，有词讼之端；主翁笞仆，防责罚之事。讲论经史，事体徒间于虚说；语歌词曲，谋为转见悠扬。见博赌，主争斗之财；遇题写，主文书之事。偶携物者，受人提携；适挽手者，遇事牵连。</p><p>此乃人事之应。</p><p>及夫舟楫在水，凭其接引而行；车马登途，藉之负戴而往。张弓挟矢者，必领荐；有箭无弓者，未可试。持刀执刃，须求快利之方。披甲操戈，可断刚强之柄。缫丝者，事务繁冗。围棋者，眼目众多。妆花刻果，终非结实之因。书影描形，皆为装点之类。络绎将成，可以问职。笔墨俱在，可以求文。偶倾盖者，主退权。忽临镜者，可赴诏。抱贵器者，有非常之用。负大木者，有不小之财。升斗宜量料而前，尺剪可裁度以用。见蹴球，有人发剔。开锁钥，遇事疏通。逢补器，终久难坚。值磨镜，再成始得。顽斧磨钢者，迟钝得利。快刀砍木者，利事伤财。裁衣服者，破后方成。造瓦器者，成后乃破。奕棋者，取之以计。张纲者，摸之以空。或持斧锯恐有伤，或涤壶觞恐有饮。或挥扇者，有相招之义。或污衣者，防谋害之侵。</p><p>此乃器物之应，即「远取诸物」之意。</p><p>虽云草木之无情，亦与卜筮而有应。故芝兰为物之瑞，松柏为寿之坚。遇椿桧，则岁久年深；遇苗菰，则朝生暮死。占产占病，得之即死之兆。枝叶飘零当萎谢，根核流落主牵连。奇葩端的虚花，嘉果可以结实。</p><p>此乃草木之应。</p><p>至于飞走，最有祯祥。故乌鸦报灾，喜虫报喜，鸿雁主朋友之信，蛇虺防毒害之谋。鼠啮衣，有小口之灾；雀噪檐，有远行之至。犬斗恐招盗贼，鸡斗主有喧争。牵羊者，喜庆将临，骑马者，出入皆利。猿猴攀木，身心不定；鲤鱼出水，变化不凡。绳拴马，疾病难安；架陷禽，囚人末脱。</p><p>此乃禽兽之应。</p><p>酒乃忘忧之物，药乃怯病之方。故酒樽忽破，乐极生悲；医师道逢，难中有救。藤萝之类堪依倚，虎豹之象可施威。耕田锄地者，事势必翻。破竹剖竿者，事势必顺。春花秋月，虽无实而关景，夏绵冬葛，虽有用而背时。凉扇，多主弃捐；晴伞，渐逢闲废。泡沫电光，虚幻难信；蛛丝蚕茧，巧计方成。</p><p>此乃杂见观物之应。</p><p>若见物形，可知字体。故石逢皮则破；人傍木为休；笠漂水畔，泣字分明。火入山林，焚形可见。三女有奸私之扰，三牛有奔走之忧。一木两火，荣耀之光。一水四鱼，鳏寡之象。人继牛倒防失脱，人言犬中忧狱囚。一斗入空门者，斗争。两丝挂白木者，乐事。一人立门，诸事有闪。二人夹木，所问必来。</p><p>此为拆字之应。</p><p>复指物名，以叶音义。如见鹿可以问禄，见蜂可以言封。梨主分别，桃主逃走。见李则问讼得理，逢冠则问名得官。鞋为百事和谐，阖则诸事可合。难以详备，在于变通。</p><p>此即物叶音之义。</p><p>及夫在我之身，实为彼事之应。故我心忧者，彼事亦忧；我心乐者，彼事亦乐。我适闲，彼当从容；我值忙，彼当窘迫。</p><p>此即自己之应，「近取诸身」之义。</p><p>欲究观人之道，须详系《易》之辞。将叛者，其辞惭；将疑者，其辞支。吉人之辞寡，躁人之辞多。诬善之人，其辞游；失其守者，其辞屈。</p><p>此一动一静之应，「近取诸身」之义。</p><p>又推五行，须详八卦。卦吉而应吉终吉，卦凶而应凶终凶。卦应一吉一凶，事体半吉半凶。明生克之理，察动静之机，事事相关，物物相合，此五行八卦及克应动静之理。活法更存乎方寸，玄机又在于师传。纵万象之纷纭，惟一理而融贯。务要相机而发，须要临事而详。</p><p>此言占卜之理在于变通之妙。</p><p>嗟夫，方朔覆射，知事物之隐微。诸葛马前，定吉凶于顷刻。皇甫坐端之妙，淳风鸟觉之占，虽所用之有殊，诚此理之无异。</p><p>此言三要灵应妙处。</p><p>可以契鬼神之妙，可以会着龟之灵。然人非三世，莫能造其玄；心非七窍，莫能悟其奥。故得其说者，宜秘；非其人者，莫传。轻泄天机，重遭阴谴。造之深，可以入道。用之久，可以通神。</p><p>此言灵应之妙，不可轻传妄授，宜秘之一人，之以重斯道也。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>方寸湛然</td><td>zhàn rán</td><td>方寸即心，湛然：清澈安静</td></tr><tr><td>灵台皎洁</td><td>jiǎo jié</td><td>灵台即心，皎洁：明亮洁净</td></tr><tr><td>汩没茫昧</td><td>gǔ mò máng mèi</td><td>沉没混乱，昏昧不明</td></tr><tr><td>俾</td><td>bǐ</td><td>使，令</td></tr><tr><td>圆通三昧</td><td>sān mèi</td><td>佛教语，三昧即正定，圆通三昧指彻底通达的境界</td></tr><tr><td>寂闻澄虑</td><td>chéng lǜ</td><td>寂静地听，澄清思虑</td></tr><tr><td>灼然</td><td>zhuó rán</td><td>明显，清楚</td></tr><tr><td>祯祥</td><td>zhēn xiáng</td><td>吉祥的征兆</td></tr><tr><td>蛇虺</td><td>shé huǐ</td><td>毒蛇，虺为小毒蛇</td></tr><tr><td>瞽者</td><td>gǔ zhě</td><td>盲人</td></tr><tr><td>攘臂</td><td>rǎng bì</td><td>捋起袖子，表示奋力争夺</td></tr><tr><td>笞仆</td><td>chī pú</td><td>鞭打仆人</td></tr><tr><td>缫丝</td><td>sāo sī</td><td>从蚕茧中抽丝</td></tr><tr><td>倾盖</td><td>qīng gài</td><td>车盖相倾，指偶然相遇</td></tr><tr><td>蹴球</td><td>cù qiú</td><td>踢球</td></tr><tr><td>张纲</td><td>zhāng gāng</td><td>撒网捕鱼</td></tr><tr><td>苗菰</td><td>miáo gū</td><td>初生的菰草，朝生暮死之物</td></tr><tr><td>奇葩</td><td>qí pā</td><td>奇异的花，此处指华而不实</td></tr><tr><td>嘉果</td><td>jiā guǒ</td><td>好的果实，结实之象</td></tr><tr><td>叶音义</td><td>yè yīn yì</td><td>以物名的谐音取义</td></tr><tr><td>阖</td><td>hé</td><td>关闭，合拢</td></tr><tr><td>阴谴</td><td>yīn qiǎn</td><td>冥冥中的惩罚</td></tr><tr><td>方朔覆射</td><td>—</td><td>东方朔以布覆物令人猜测，知隐微之事</td></tr><tr><td>诸葛马前</td><td>—</td><td>诸葛亮马前课，顷刻定吉凶</td></tr><tr><td>皇甫坐端</td><td>—</td><td>皇甫真人坐而起卦之妙</td></tr><tr><td>淳风鸟觉</td><td>—</td><td>李淳风见鸟而占之法</td></tr><tr><td>着龟</td><td>zhuó guī</td><td>灼龟甲以占卜</td></tr><tr><td>人非三世</td><td>—</td><td>非经三世修炼，难造其玄</td></tr></tbody></table><hr><h2 id="📖-白话译文" tabindex="-1">📖 白话译文 <a class="header-anchor" href="#📖-白话译文" aria-label="Permalink to &quot;📖 白话译文&quot;">​</a></h2><h3 id="序" tabindex="-1">序 <a class="header-anchor" href="#序" aria-label="Permalink to &quot;序&quot;">​</a></h3><p>《易》是性理之学，性理存于人心之中。当心境清澈，灵台洁净，没有一丝杂念，没有一粒尘埃——这时候，性理完整地存在，《易》就在我心中，浑然就是《易》，这是先天之《易》。</p><p>然而一旦思虑萌动，事端忽起，外物牵挂于心，如云遮室，如尘蒙镜——这时候，心就沉没混乱，原本《易》在心中的那个状态，消失了。</p><p>所以三要的妙处，在于运用耳、目、心三者的虚灵，使之感应于事物。耳的聪敏，目的明察，都统摄于心。事根于心，心该乎事——事情未萌发时，连鬼神都测不到；事情一萌于心，鬼神就知道了。</p><p>吉凶悔吝有其数，我如何能预知？答案只有一个：「求诸吾心易之妙而已。」</p><p>于是寂然不动，静虑诚存，观变玩占，运用三要——使别人视而不见的，我能见到；别人听而不闻的，我能听到。如形之被看见，如音之被告知，我了然鉴之。《易》在吾心，三要不虚，灵应之妙自得。</p><h3 id="三要灵应篇-各节要义" tabindex="-1">三要灵应篇（各节要义） <a class="header-anchor" href="#三要灵应篇-各节要义" aria-label="Permalink to &quot;三要灵应篇（各节要义）&quot;">​</a></h3><p><strong>总纲</strong>：耳听音知吉凶，目见形知善恶，心察理知祸福。如谷之应声，如影之随形。出于《周易》「远取诸物，近取诸身」之法。</p><p><strong>占物克应</strong>：遇吉兆则吉，见凶兆则凶。圆者事成，缺者事败。</p><p><strong>仰观天文</strong>：云开见日事增辉，烟雾障空物失色。颠风飘荡，震雷虚惊。月当面近清光，雨沾衣蒙恩泽。</p><p><strong>俯察地理</strong>：重山阻隔，重泽浸润。水流事通，土积事滞。石坚心始得，沙放手即开。浪激波涛惊，坡崩田土失。旱沼心力竭，枯林相貌衰。</p><p><strong>人品之应</strong>：荣官见贵，富商问财。童子哭泣忧子孙，吏卒叫嚣忌官讼。二男二女重婚，一僧一道独处。妇人笑语阴喜，女子牵连阴私。匠氏门庭改换，宰夫骨肉分离。猎者野外之财，渔者水边之利。妊妇事荫于内，瞽者虑根于心。</p><p><strong>近取诸身</strong>：摇手莫为，掉头不肯。喷嚏方泣，搔首有忧。足动有行，交臂有失。屈指多阻，嘘气悲忧。舌出是非，背向闪失。攘臂争夺，下膝屈求。</p><p><strong>人事之应</strong>：童子授书词讼，主翁笞仆责罚。讲经虚说，歌曲悠扬。博赌争财，题写文书。携物受提携，挽手遇牵连。</p><p><strong>器物之应</strong>：舟楫接引，车马负戴。张弓必荐，有箭无弓未可试。刀刃求利，甲戈断刚。缫丝繁冗，围棋众多。络绎问职，笔墨求文。倾盖退权，临镜赴诏。蹴球发剔，开锁疏通。补器难坚，磨镜再成。裁衣破后方成，造瓦成后乃破。</p><p><strong>草木之应</strong>：芝兰为瑞，松柏为寿。椿桧岁久，苗菰朝生暮死（占产占病得之即死兆）。枝叶飘零萎谢，根核流落牵连。奇葩虚花，嘉果结实。</p><p><strong>禽兽之应</strong>：乌鸦报灾，喜虫报喜。鸿雁朋友信，蛇虺毒害谋。鼠啮衣小口灾，雀噪檐远行至。犬斗盗贼，鸡斗喧争。牵羊喜庆，骑马出入利。猿猴不定，鲤鱼变化。绳拴马疾病难安，架陷禽囚人未脱。</p><p><strong>杂见观物</strong>：酒樽破乐极生悲，医师逢难中有救。藤萝依倚，虎豹施威。耕锄事翻，破竹事顺。春花秋月关景无实，夏绵冬葛背时有用。凉扇弃捐，晴伞闲废。泡沫电光虚幻，蛛丝蚕茧巧计方成。</p><p><strong>拆字之应</strong>：石逢皮则破，人傍木为休，笠漂水畔泣字，火入山林焚形。三女奸私，三牛奔走。一木两火荣耀，一水四鱼鳏寡。人继牛倒失脱，人言犬中狱囚。一斗入空门斗争，两丝挂白木乐事。一人立门诸事闪，二人夹木所问必来。</p><p><strong>物叶音义</strong>：鹿→禄，蜂→封，梨→离别，桃→逃走，李→理（得理），冠→官，鞋→谐，阖→合。</p><p><strong>自己之应</strong>：我心忧彼事亦忧，我心乐彼事亦乐。我闲彼从容，我忙彼窘迫。</p><p><strong>观人之辞</strong>：将叛者辞惭，将疑者辞支。吉人辞寡，躁人辞多。诬善者辞游，失守者辞屈。</p><p><strong>总结</strong>：卦吉应吉终吉，卦凶应凶终凶。卦应一吉一凶，事体半吉半凶。活法存乎方寸，玄机在于师传。纵万象纷纭，惟一理融贯。</p><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、三要的本质-虚灵感通" tabindex="-1">一、三要的本质：虚灵感通 <a class="header-anchor" href="#一、三要的本质-虚灵感通" aria-label="Permalink to &quot;一、三要的本质：虚灵感通&quot;">​</a></h3><p>三要——耳、目、心——不是三个独立的工具，而是一个整体的感知状态。</p><p>序里说得很清楚：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心境清净（无一毫之干，无一尘之累）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>《易》在吾心（先天之《易》）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>三要虚灵（耳聪·目明·心澄）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>感应于事物（灵应）</span></span></code></pre></div><p>一旦心被外物牵挂（「如云之蔽室，如尘之蒙镜」），这个感通就断了。</p><p>所以三要的前提，不是技巧，是<strong>心的状态</strong>。</p><h3 id="二、三要灵应的十四类应验" tabindex="-1">二、三要灵应的十四类应验 <a class="header-anchor" href="#二、三要灵应的十四类应验" aria-label="Permalink to &quot;二、三要灵应的十四类应验&quot;">​</a></h3><p>本篇将克应分为十四类，每类后都有原文小结句，结构非常清晰：</p><table tabindex="0"><thead><tr><th>类别</th><th>原文小结</th><th>核心逻辑</th></tr></thead><tbody><tr><td>占物克应</td><td>见吉则吉，遇凶则凶</td><td>象的直接对应</td></tr><tr><td>仰观天文</td><td>以验人事</td><td>天象映人事</td></tr><tr><td>俯察地理</td><td>以验人事</td><td>地象映人事</td></tr><tr><td>人品之应</td><td>以验人事</td><td>所遇之人即事之象</td></tr><tr><td>近取诸身（动作）</td><td>近取诸身之应</td><td>身体动作即象</td></tr><tr><td>人事之应</td><td>人事之应</td><td>所见之事即象</td></tr><tr><td>器物之应</td><td>远取诸物之意</td><td>器物象意直取</td></tr><tr><td>草木之应</td><td>草木之应</td><td>植物生死荣枯即象</td></tr><tr><td>禽兽之应</td><td>禽兽之应</td><td>动物行为即象</td></tr><tr><td>杂见观物</td><td>杂见观物之应</td><td>综合观物</td></tr><tr><td>拆字之应</td><td>拆字之应</td><td>字形分解取象</td></tr><tr><td>物叶音义</td><td>物叶音之义</td><td>谐音取义</td></tr><tr><td>自己之应</td><td>近取诸身之义</td><td>己身感受即彼事之象</td></tr><tr><td>观人之辞</td><td>近取诸身之义</td><td>言辞即心之象</td></tr></tbody></table><p>这十四类，全部来自《周易·系辞》的两句话：</p><blockquote><p>「<strong>远取诸物，近取诸身</strong>」</p></blockquote><p>远取诸物：天文·地理·器物·草木·禽兽·杂物<br> 近取诸身：人品·动作·人事·自己·言辞</p><h3 id="三、几个特别值得注意的应验" tabindex="-1">三、几个特别值得注意的应验 <a class="header-anchor" href="#三、几个特别值得注意的应验" aria-label="Permalink to &quot;三、几个特别值得注意的应验&quot;">​</a></h3><p><strong>自己之应</strong>——这是最容易被忽视，也最深刻的一类：</p><blockquote><p>「我心忧者，彼事亦忧；我心乐者，彼事亦乐。我适闲，彼当从容；我值忙，彼当窘迫。」</p></blockquote><p>占卜者自身的状态，就是被占之事的镜子。这不是说占卜者影响了结果，而是说：<strong>感通已经发生，占卜者的心已经与被占之事同频</strong>。</p><p><strong>观人之辞</strong>——出自《易·系辞下》：</p><blockquote><p>「将叛者其辞惭，中心疑者其辞枝，吉人之辞寡，躁人之辞多，诬善之人其辞游，失其守者其辞屈。」</p></blockquote><p>这是《易》原文，邵雍直接引入三要，说明言辞本身就是象。一个人说话的方式，已经透露了他内心的状态和事情的走向。</p><p><strong>拆字之应</strong>——这是最有趣的一类，用字形来取象：</p><table tabindex="0"><thead><tr><th>字形描述</th><th>对应字</th><th>取象逻辑</th></tr></thead><tbody><tr><td>石逢皮</td><td>破</td><td>石+皮=破</td></tr><tr><td>人傍木</td><td>休</td><td>人+木=休</td></tr><tr><td>笠漂水畔</td><td>泣</td><td>笠（立）+水=泣</td></tr><tr><td>火入山林</td><td>焚</td><td>火+林=焚</td></tr><tr><td>三女</td><td>奸</td><td>三个女=奸</td></tr><tr><td>三牛</td><td>犇（奔）</td><td>三牛=犇（奔走）</td></tr><tr><td>一木两火</td><td>炎</td><td>木上两火=炎（荣耀之光）</td></tr><tr><td>一水四鱼</td><td>鱻（鲜）</td><td>一水四鱼→鳏寡之象（鲜→鳏，谐音）</td></tr><tr><td>一斗入空门</td><td>闹（斗争）</td><td>斗+门=闹</td></tr><tr><td>两丝挂白木</td><td>乐</td><td>丝+木=乐（乐器）</td></tr><tr><td>一人立门</td><td>闪</td><td>人+门=闪</td></tr><tr><td>二人夹木</td><td>来</td><td>人+木+人=来</td></tr></tbody></table><h3 id="四、卦与应的关系" tabindex="-1">四、卦与应的关系 <a class="header-anchor" href="#四、卦与应的关系" aria-label="Permalink to &quot;四、卦与应的关系&quot;">​</a></h3><p>末段总结了卦与三要克应的配合关系：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卦吉 + 应吉 = 终吉（大吉）</span></span>
<span class="line"><span>卦凶 + 应凶 = 终凶（大凶）</span></span>
<span class="line"><span>卦吉 + 应凶 = 半吉半凶</span></span>
<span class="line"><span>卦凶 + 应吉 = 半吉半凶</span></span></code></pre></div><p>这与占卜总诀「俱吉则大吉，俱凶则大凶，有吉有凶则详审」完全对应。</p><p>三要克应是卦象判断的<strong>印证层</strong>，不是替代层。卦为主，应为辅；两者一致则确定，两者相反则存疑，需详审。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="序里那面镜子" tabindex="-1">序里那面镜子 <a class="header-anchor" href="#序里那面镜子" aria-label="Permalink to &quot;序里那面镜子&quot;">​</a></h3><p>序里有两个意象，是全篇最美的：</p><blockquote><p>「如云之蔽室，如尘之蒙镜」</p></blockquote><p>心是镜子。镜子本来能照见一切，但蒙了尘就照不清了。</p><p>三要的功夫，不是在镜子上加什么，而是<strong>擦去尘埃</strong>。</p><p>心清净了，耳目自然聪明；耳目聪明了，万物的象自然进来。不是我去找象，是象来找我——这与序里「心致而目玩」的状态完全一致。</p><h3 id="「思虑未动-鬼神不知」" tabindex="-1">「思虑未动，鬼神不知」 <a class="header-anchor" href="#「思虑未动-鬼神不知」" aria-label="Permalink to &quot;「思虑未动，鬼神不知」&quot;">​</a></h3><p>这句话非常深。</p><p>事情还没有在心里萌动的时候，连鬼神都不知道会发生什么。一旦事情萌于心——你开始想这件事，开始感受这件事——鬼神就知道了，数就有了，象就显现了。</p><p>这说明：<strong>占卜的触发点，是心的萌动，不是外部事件</strong>。</p><p>外部事件（雀争枝、牛鸣、风起）只是一个触发器，真正让占卜成立的，是占卜者的心与事情之间的感通。没有这个感通，再多的外部触发也是噪音。</p><h3 id="万象归一理" tabindex="-1">万象归一理 <a class="header-anchor" href="#万象归一理" aria-label="Permalink to &quot;万象归一理&quot;">​</a></h3><p>末段说：「纵万象之纷纭，惟一理而融贯。」</p><p>十四类克应，看起来繁杂——天文、地理、人品、动作、器物、草木、禽兽、拆字、谐音……</p><p>但背后只有一个原则：<strong>象与象之间，有内在的感通</strong>。</p><p>圆的象是完整，缺的象是损毁——不管是圆形的器物，还是圆满的月亮，还是说话圆滑的人，都是同一个象在不同形式上的显现。</p><p>感受到了这个「一理」，十四类就不是十四个要背的规则，而是同一种感知能力在不同场景下的应用。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>三要：耳·目·心，虚灵感通，非技巧而是状态</li><li>心如镜：清净则照见，蒙尘则茫昧</li><li>「思虑未动，鬼神不知」：感通在于心的萌动</li><li>十四类克应：远取诸物·近取诸身，万象皆可为应</li><li>自己之应：占者自身状态即被占之事的镜子</li><li>观人之辞：言辞即心之象（出自《易·系辞下》）</li><li>拆字·叶音：字形字音皆可取象</li><li>卦与应配合：俱吉大吉，俱凶大凶，一吉一凶详审</li><li>「纵万象之纷纭，惟一理而融贯」：万象归一</li></ul><p><strong>规律提炼</strong></p><ol><li>三要不是三个独立工具，是心清净后自然具备的感知状态</li><li>克应是卦象的印证层，卦为主，应为辅，两者一致则确定</li><li>十四类克应全部来自「远取诸物，近取诸身」，框架简单，应用无穷</li><li>自己之应是最深的一类——占者与被占之事已经同频，己身即镜</li><li>「活法更存乎方寸」——所有规则的活用，最终回到心的感知</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之一「心易之妙」→ 此篇「求诸吾心易之妙」：心易的具体内容在此展开</li><li>篇之一「要在圆机，不可执」→ 此篇「活法更存乎方寸，玄机又在于师传」：同一精神</li><li>篇之二占卜总诀第三步「克应」→ 此篇将克应展开为十四类，完整呈现</li><li>序「心致而目玩」→ 此篇序「方寸湛然，灵台皎洁」：同一种心的状态</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-014</strong>：序中「此先师刘先生（江夏人，号湛然子）得之王屋山人高处士云岩」，以及篇末传承列表「鬼谷子·严君平·东方朔·诸葛孔明……邵康节……刘湛然·朱清灵子」——三要灵应篇的作者并非邵雍本人，而是后人（清灵子朱虚，宝庆四年即1228年，距邵雍去世已150余年）整理并托名于邵雍传承之下。此篇与邵雍原著的关系，是「后人补入」还是「邵雍传承脉络中的正式文本」？此问题影响对本篇权威性的判断，存疑备注。</p></blockquote><blockquote><p><strong>❓****-015</strong>：「人非三世，莫能造其玄；心非七窍，莫能悟其奥」——「三世」指三世修炼（佛教语），「七窍」指感知完备。这两句话暗示三要灵应是需要长期修炼才能掌握的功夫，而非短期可得。与前文「得此者，幸甚秘之」呼应。但「秘之」的态度与「以示后学之法则」的初衷似有张力，待全书读完后整体理解。</p></blockquote>`,132)])])}const u=d(n,[["render",e]]);export{c as __pageData,u as default};
